messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Low Poly Humanoid Exercise</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
    </style>
</head>
<body>
<script type="module">
    import * as THREE from './three.module.js';

    // --- Configuration ---
    const CYCLE_DURATION = 10; // seconds
    const STATE_STILL = 'still';
    const STATE_WALK = 'walk';
    const STATE_RUN = 'run';

    // --- Scene Setup ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x87CEEB); // Sky blue
    scene.fog = new THREE.Fog(0x87CEEB, 10, 50);

    const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 100);
    // Side-on camera setup
    camera.position.set(0, 3, 8);
    camera.lookAt(0, 1, 0);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    document.body.appendChild(renderer.domElement);

    // --- Lighting ---
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
    dirLight.position.set(-5, 10, 5);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 1024;
    dirLight.shadow.mapSize.height = 1024;
    dirLight.shadow.camera.near = 0.5;
    dirLight.shadow.camera.far = 50;
    dirLight.shadow.camera.left = -10;
    dirLight.shadow.camera.right = 10;
    dirLight.shadow.camera.top = 10;
    dirLight.shadow.camera.bottom = -10;
    scene.add(dirLight);

    // --- Materials ---
    const matBody = new THREE.MeshStandardMaterial({ color: 0xe74c3c, flatShading: true }); // Red shirt
    const matLegs = new THREE.MeshStandardMaterial({ color: 0x34495e, flatShading: true }); // Dark pants
    const matSkin = new THREE.MeshStandardMaterial({ color: 0xf1c40f, flatShading: true }); // Skin
    const matGround = new THREE.MeshStandardMaterial({ color: 0x2c3e50, flatShading: true });

    // --- Geometry Helpers ---
    function createLimb(radiusTop, radiusBottom, height) {
        return new THREE.CylinderGeometry(radiusTop, radiusBottom, height, 6); // Low poly count
    }

    // --- Character Construction ---
    const character = new THREE.Group();

    // Pivot points (Hips and Shoulders)
    const hipPivot = new THREE.Group();
    const leftHipJoint = new THREE.Group();
    const rightHipJoint = new THREE.Group();
    const leftShoulderJoint = new THREE.Group();
    const rightShoulderJoint = new THREE.Group();

    // 1. Legs
    const legGeo = createLimb(0.12, 0.1, 1.0);
    const footGeo = new THREE.BoxGeometry(0.2, 0.1, 0.4);

    // Left Leg
    const leftLegMesh = new THREE.Mesh(legGeo, matLegs);
    leftLegMesh.position.y = -0.5;
    leftLegMesh.castShadow = true;
    const leftFootMesh = new THREE.Mesh(footGeo, matLegs);
    leftFootMesh.position.y = -0.5; // Bottom of leg
    leftFootMesh.position.z = 0.1;
    leftFootMesh.castShadow = true;
    leftLegMesh.add(leftFootMesh);
    leftHipJoint.add(leftLegMesh);
    leftHipJoint.position.set(-0.2, 0, 0); // Offset from hip center

    // Right Leg
    const rightLegMesh = new THREE.Mesh(legGeo, matLegs);
    rightLegMesh.position.y = -0.5;
    rightLegMesh.castShadow = true;
    const rightFootMesh = new THREE.Mesh(footGeo, matLegs);
    rightFootMesh.position.y = -0.5;
    rightFootMesh.position.z = 0.1;
    rightFootMesh.castShadow = true;
    rightLegMesh.add(rightFootMesh);
    rightHipJoint.add(rightLegMesh);
    rightHipJoint.position.set(0.2, 0, 0);

    // 2. Torso
    const torsoGeo = new THREE.BoxGeometry(0.4, 0.7, 0.25);
    const torsoMesh = new THREE.Mesh(torsoGeo, matBody);
    torsoMesh.position.y = 0.35;
    torsoMesh.castShadow = true;

    // 3. Head
    const headGeo = new THREE.BoxGeometry(0.3, 0.3, 0.3);
    const headMesh = new THREE.Mesh(headGeo, matSkin);
    headMesh.position.y = 0.5;
    headMesh.castShadow = true;

    // 4. Arms
    const armGeo = createLimb(0.08, 0.08, 0.7);
    const handGeo = new THREE.BoxGeometry(0.1, 0.1, 0.1);

    // Left Arm
    const leftArmMesh = new THREE.Mesh(armGeo, matSkin);
    leftArmMesh.position.y = -0.35;
    leftArmMesh.castShadow = true;
    const leftHandMesh = new THREE.Mesh(handGeo, matSkin);
    leftHandMesh.position.y = -0.35;
    leftHandMesh.castShadow = true;
    leftArmMesh.add(leftHandMesh);
    leftShoulderJoint.add(leftArmMesh);
    leftShoulderJoint.position.set(-0.25, 0.6, 0); // Shoulder position relative to torso

    // Right Arm
    const rightArmMesh = new THREE.Mesh(armGeo, matSkin);
    rightArmMesh.position.y = -0.35;
    rightArmMesh.castShadow = true;
    const rightHandMesh = new THREE.Mesh(handGeo, matSkin);
    rightHandMesh.position.y = -0.35;
    rightHandMesh.castShadow = true;
    rightArmMesh.add(rightHandMesh);
    rightShoulderJoint.add(rightArmMesh);
    rightShoulderJoint.position.set(0.25, 0.6, 0);

    // Assemble Character
    hipPivot.add(leftHipJoint);
    hipPivot.add(rightHipJoint);
    // Torso is attached to hips, but we need a group to handle the forward lean separately from leg rotation
    const upperBody = new THREE.Group();
    upperBody.add(torsoMesh);
    upperBody.add(headMesh);
    upperBody.add(leftShoulderJoint);
    upperBody.add(rightShoulderJoint);

    // We attach the UpperBody to the HipPivot so they move together, 
    // but we can rotate UpperBody for leaning.
    hipPivot.add(upperBody);

    // Position the whole character so feet touch ground (y=0)
    // Leg length is 1.0, pivot is at y=0 relative to hip. Feet are at y=-0.5 relative to joint.
    // So hip is at y=0.5 relative to feet.
    hipPivot.position.y = 1.0; 

    character.add(hipPivot);
    scene.add(character);

    // --- Ground (Treadmill) ---
    const groundGeo = new THREE.BoxGeometry(100, 0.5, 4);
    const ground = new THREE.Mesh(groundGeo, matGround);
    ground.position.y = -0.25;
    ground.receiveShadow = true;
    scene.add(ground);

    // Add some markings to the treadmill to show movement
    const markingGeo = new THREE.BoxGeometry(0.2, 0.05, 3);
    const markingMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
    for(let i=0; i<20; i++) {
        const m = new THREE.Mesh(markingGeo, markingMat);
        m.position.set(i * 2 - 20, 0.01, 0);
        ground.add(m);
    }

    // --- Animation Logic ---
    const clock = new THREE.Clock();

    function getPoseParams(time) {
        const cycleTime = time % CYCLE_DURATION;

        // 0-2: Still
        // 2-5: Walk (3s)
        // 5-8: Run (3s)
        // 8-10: Still (2s)

        let state = STATE_STILL;
        let phase = 0; // 0 to 1 within the walking/running segment

        if (cycleTime < 2) {
            state = STATE_STILL;
            phase = 0;
        } else if (cycleTime < 5) {
            state = STATE_WALK;
            phase = (cycleTime - 2) / 3;
        } else if (cycleTime < 8) {
            state = STATE_RUN;
            phase = (cycleTime - 5) / 3;
        } else {
            state = STATE_STILL;
            phase = 0;
        }

        return { state, phase };
    }

    function animate() {
        requestAnimationFrame(animate);

        const time = clock.getElapsedTime();
        const { state, phase } = getPoseParams(time);

        // --- Treadmill Movement ---
        let speed = 0;
        if (state === STATE_WALK) speed = 2;
        if (state === STATE_RUN) speed = 6;

        // Move ground texture/child objects to simulate treadmill belt moving
        // Since we can't easily move texture UVs on a basic box without custom shader, 
        // we just move the markings.
        const markings = ground.children;
        markings.forEach(m => {
            m.position.x -= speed * 0.016; // approx delta time
            if (m.position.x < -10) m.position.x += 40; // Loop markings
        });

        // --- Character Animation ---

        // Reset rotations
        leftHipJoint.rotation.x = 0;
        rightHipJoint.rotation.x = 0;
        leftShoulderJoint.rotation.x = 0;
        rightShoulderJoint.rotation.x = 0;
        upperBody.rotation.x = 0; // Forward lean reset

        if (state === STATE_STILL) {
            // Idle pose: slight bend in knees, arms down
            leftHipJoint.rotation.x = -0.1;
            rightHipJoint.rotation.x = -0.1;
            leftShoulderJoint.rotation.x = 0.1;
            rightShoulderJoint.rotation.x = 0.1;
            upperBody.rotation.x = 0;
        } 
        else if (state === STATE_WALK) {
            // Walk Params
            const amplitude = 0.6; // Radians
            const freq = 2.0; // Cycles per walk duration

            // Legs
            leftHipJoint.rotation.x = Math.sin(phase * Math.PI * 2 * freq) * amplitude;
            rightHipJoint.rotation.x = Math.sin(phase * Math.PI * 2 * freq + Math.PI) * amplitude;

            // Arms (Opposite phase to legs)
            leftShoulderJoint.rotation.x = Math.sin(phase * Math.PI * 2 * freq + Math.PI) * amplitude * 0.8;
            rightShoulderJoint.rotation.x = Math.sin(phase * Math.PI * 2 * freq) * amplitude * 0.8;

            // Slight bob
            character.position.y = Math.abs(Math.sin(phase * Math.PI * 2 * freq)) * 0.05;
        } 
        else if (state === STATE_RUN) {
            // Run Params
            const amplitude = 1.2; // Larger swings
            const freq = 3.0; // Faster cycles

            // Legs
            leftHipJoint.rotation.x = Math.sin(phase * Math.PI * 2 * freq) * amplitude;
            rightHipJoint.rotation.x = Math.sin(phase * Math.PI * 2 * freq + Math.PI) * amplitude;

            // Arms (Tighter swing, usually elbows bent, but we simulate by rotation)
            // Running arms swing more vertically but we use X rotation here
            leftShoulderJoint.rotation.x = Math.sin(phase * Math.PI * 2 * freq + Math.PI) * amplitude * 0.9;
            rightShoulderJoint.rotation.x = Math.sin(phase * Math.PI * 2 * freq) * amplitude * 0.9;

            // Forward Lean
            upperBody.rotation.x = 0.3; // Lean forward

            // Larger vertical bob
            character.position.y = Math.abs(Math.sin(phase * Math.PI * 2 * freq)) * 0.15;
        }

        renderer.render(scene, camera);
    }

    // Handle Resize
    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });

    // Start
    animate();

</script>
</body>
</html>
```
